// Appends Skin Care ids 351-367 + Facial Treatments ids 368-400
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const scT=`"Skin Care"`, scTes=`"Cuidado de la Piel"`, scPt=`"Skin Care"`, scPtes=`"Cuidado de la Piel"`
const ftT=`"Facial Treatments"`, ftTes=`"Tratamientos Faciales"`, ftPt=`"Facial Treatments"`, ftPtes=`"Tratamientos Faciales"`

function fmt(q, t, tes, pt, ptes) {
  return `  { id: ${q.id}, topic: ${t}, topic_es: ${tes}, psi_topic: ${pt}, psi_topic_es: ${ptes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const SC = [
  { id: 351, question: "Couperose skin is best described as:", question_es: "La piel con cuperosis se describe mejor como:", options: ["Skin showing visible, distended capillaries (redness/red thread-like vessels) near the surface, often on the cheeks and nose, due to weakened or dilated blood vessel walls", "Skin with excessive sebum production and enlarged pores across the entire face", "Skin with patches of hyperpigmentation caused by sun exposure", "Skin that is extremely dehydrated and flaking due to lack of lipids"], options_es: ["Piel que muestra capilares visibles y dilatados (enrojecimiento/vasos en forma de hilos rojos) cerca de la superficie, a menudo en las mejillas y la nariz, debido a paredes de vasos sanguíneos debilitadas o dilatadas", "Piel con producción excesiva de sebo y poros agrandados en toda la cara", "Piel con manchas de hiperpigmentación causadas por la exposición al sol", "Piel extremadamente deshidratada y descamada por falta de lípidos"], correct: 0, explanation: "Couperose describes skin with visible dilated capillaries, usually appearing as fine red thread-like lines on the cheeks, nose, and chin. It results from weakened vessel walls and is aggravated by heat, sun, alcohol, and spicy foods. Estheticians should avoid harsh stimulation, hot steam, and aggressive massage on couperose areas." },
  { id: 352, question: "A client describes their skin as feeling tight and looking flaky after cleansing, but their T-zone still appears oily by midday. This skin is most likely:", question_es: "Un cliente describe su piel como tensa y escamosa después de limpiarla, pero su zona T todavía aparece grasosa al mediodía. Esta piel es más probablemente:", options: ["Dehydrated combination skin — lacking water (causing tightness/flaking) while the T-zone still produces normal or excess oil; dehydration is a temporary water deficiency, distinct from the oil-producing skin type itself", "True dry skin type — all areas of the face lack both oil and water and the T-zone observation is incorrect", "Oily skin type — the flaking is actually a sign of excess sebum hardening on the surface", "Normal skin — the described symptoms are within the expected range and require no special care"], options_es: ["Piel mixta deshidratada — carece de agua (causando tirantez/descamación) mientras que la zona T todavía produce sebo normal o en exceso; la deshidratación es una deficiencia temporal de agua, distinta del tipo de piel productora de aceite en sí", "Tipo de piel verdaderamente seca — todas las áreas de la cara carecen tanto de aceite como de agua y la observación de la zona T es incorrecta", "Tipo de piel grasa — la descamación es en realidad un signo de sebo excesivo endureciéndose en la superficie", "Piel normal — los síntomas descritos están dentro del rango esperado y no requieren cuidado especial"], correct: 0, explanation: "Dehydration (lack of water) is a condition that can occur in any skin type, including oily skin. A client can simultaneously have an oily T-zone (oil/sebum production, a skin type characteristic) and dehydrated cheeks (lacking water, a temporary condition). Distinguishing dehydration (condition) from dryness (type) is essential for selecting appropriate hydrating, non-comedogenic products." },
  { id: 353, question: "Hyperkeratosis refers to:", question_es: "La hiperqueratosis se refiere a:", options: ["An abnormal thickening of the stratum corneum due to excess keratin production or buildup of dead skin cells, often seen as rough, scaly, or thickened patches", "A deficiency of keratin in the epidermis leading to fragile, thin skin", "Excess melanin production resulting in dark patches on the skin", "Inflammation of the sebaceous glands resulting in pustules"], options_es: ["Un engrosamiento anormal del estrato córneo debido a la producción excesiva de queratina o acumulación de células muertas de la piel, a menudo visto como parches ásperos, escamosos o engrosados", "Una deficiencia de queratina en la epidermis que conduce a una piel frágil y delgada", "Producción excesiva de melanina que resulta en manchas oscuras en la piel", "Inflamación de las glándulas sebáceas que resulta en pústulas"], correct: 0, explanation: "Hyperkeratosis is the thickening of the stratum corneum from excess keratin production or accumulation of dead corneocytes that fail to shed properly. It can present as rough patches, calluses, or scaly texture. Exfoliation treatments (mechanical or chemical) help normalize cell turnover and reduce hyperkeratotic buildup." },
  { id: 354, question: "Which statement about skin's acid mantle is correct?", question_es: "¿Cuál afirmación sobre el manto ácido de la piel es correcta?", options: ["It is a thin, slightly acidic film (pH approximately 4.5–5.5) on the skin's surface composed of sebum and sweat that helps protect against bacteria, pollutants, and moisture loss", "It is a layer of dead skin cells located in the dermis that regulates blood flow", "It is composed primarily of melanin and protects against UV radiation only", "It is a synthetic barrier applied through professional treatments and is not naturally present on skin"], options_es: ["Es una película delgada y ligeramente ácida (pH aproximadamente 4.5–5.5) en la superficie de la piel compuesta de sebo y sudor que ayuda a proteger contra bacterias, contaminantes y pérdida de humedad", "Es una capa de células muertas de la piel ubicada en la dermis que regula el flujo sanguíneo", "Está compuesta principalmente de melanina y protege solo contra la radiación UV", "Es una barrera sintética aplicada a través de tratamientos profesionales y no está naturalmente presente en la piel"], correct: 0, explanation: "The acid mantle is a naturally occurring, slightly acidic film on the skin's surface (pH ~4.5–5.5) formed from sebum, sweat, and amino acids. It inhibits the growth of harmful bacteria and fungi, helps maintain the skin barrier, and reduces transepidermal water loss. Harsh alkaline cleansers can disrupt the acid mantle and compromise the skin's defenses." },
  { id: 355, question: "Milia are best described as:", question_es: "Los milios se describen mejor como:", options: ["Small, hard, white cysts of trapped keratin beneath the skin surface, with no visible pore opening, commonly found around the eyes and cheeks", "Open comedones filled with oxidized sebum that appear black at the surface", "Inflamed, pus-filled lesions caused by bacterial infection of a hair follicle", "Flat, brown patches of pigmentation caused by excess melanin production"], options_es: ["Pequeños quistes duros y blancos de queratina atrapada debajo de la superficie de la piel, sin abertura de poro visible, comúnmente encontrados alrededor de los ojos y mejillas", "Comedones abiertos llenos de sebo oxidado que aparecen negros en la superficie", "Lesiones inflamadas y llenas de pus causadas por infección bacteriana de un folículo piloso", "Manchas planas y marrones de pigmentación causadas por exceso de producción de melanina"], correct: 0, explanation: "Milia are small, firm, white or yellowish keratin-filled cysts trapped beneath the skin with no follicular opening to the surface. Unlike comedones, they cannot be extracted with standard comedone extraction technique because there is no pore opening; they typically require lancing by a qualified professional (often outside the esthetician's scope) or removal via exfoliation over time." },
  { id: 356, question: "The primary purpose of a toner in a basic facial treatment is to:", question_es: "El propósito principal de un tónico en un tratamiento facial básico es:", options: ["Remove residual cleanser and debris, help restore the skin's natural pH after cleansing, and provide a light layer of hydration or astringency depending on the formulation", "Permanently shrink pore size and eliminate the need for moisturizer", "Replace the function of sunscreen by providing UV protection", "Exfoliate the deepest layers of the epidermis through chemical action"], options_es: ["Eliminar los residuos de limpiador y suciedad, ayudar a restaurar el pH natural de la piel después de la limpieza y proporcionar una ligera capa de hidratación o astringencia según la formulación", "Reducir permanentemente el tamaño de los poros y eliminar la necesidad de humectante", "Reemplazar la función del protector solar proporcionando protección UV", "Exfoliar las capas más profundas de la epidermis a través de acción química"], correct: 0, explanation: "Toners are applied after cleansing to remove any remaining residue, help rebalance the skin's pH (since many cleansers are slightly alkaline), and prepare the skin to better absorb subsequent products. Depending on formulation, toners can also provide mild hydration, soothing, or astringent benefits — but they do not replace sunscreen, permanently change pore size, or substitute for exfoliation." },
  { id: 357, question: "A client has several small, rough, sandpaper-like bumps on the back of their upper arms that do not respond to typical moisturizing. This is most consistent with:", question_es: "Un cliente tiene varios pequeños bultos ásperos similares al papel de lija en la parte posterior de los brazos superiores que no responden a la hidratación típica. Esto es más consistente con:", options: ["Keratosis pilaris — a common condition where excess keratin forms hard plugs within hair follicles, creating small rough bumps, often on the arms and thighs; gentle exfoliation and emollient products may help manage but not cure it", "Rosacea — a vascular condition that causes persistent facial redness and bumps", "Psoriasis — an autoimmune condition producing thick silvery scales primarily on the scalp and joints", "Tinea corporis — a fungal infection presenting as ring-shaped rashes"], options_es: ["Queratosis pilar — una condición común donde el exceso de queratina forma tapones duros dentro de los folículos pilosos, creando pequeños bultos ásperos, a menudo en los brazos y muslos; la exfoliación suave y los productos emolientes pueden ayudar a manejarla pero no curarla", "Rosácea — una condición vascular que causa enrojecimiento facial persistente y bultos", "Psoriasis — una condición autoinmune que produce escamas plateadas gruesas principalmente en el cuero cabelludo y las articulaciones", "Tinea corporis — una infección fúngica que se presenta como erupciones en forma de anillo"], correct: 0, explanation: "Keratosis pilaris is a very common, harmless condition caused by keratin buildup plugging hair follicles, producing rough, small bumps often described as 'chicken skin,' commonly on the upper arms, thighs, and cheeks. While not curable, gentle exfoliation (chemical or mechanical) combined with regular moisturizing can improve its appearance over time." },
  { id: 358, question: "Erythema, as observed during or after a facial treatment, refers to:", question_es: "El eritema, observado durante o después de un tratamiento facial, se refiere a:", options: ["Redness of the skin caused by dilation of blood capillaries near the surface, often a normal short-term response to stimulation, heat, friction, or extraction", "A permanent darkening of the skin caused by excess melanin deposition", "A bacterial infection requiring antibiotic treatment", "A buildup of dead skin cells forming a rough, scaly texture"], options_es: ["Enrojecimiento de la piel causado por la dilatación de los capilares sanguíneos cerca de la superficie, a menudo una respuesta normal a corto plazo a la estimulación, el calor, la fricción o la extracción", "Un oscurecimiento permanente de la piel causado por el depósito excesivo de melanina", "Una infección bacteriana que requiere tratamiento con antibióticos", "Una acumulación de células muertas de la piel que forma una textura áspera y escamosa"], correct: 0, explanation: "Erythema is redness resulting from increased blood flow to capillaries near the skin's surface. It is a common, normal, and typically temporary response to facial treatments involving stimulation such as massage, steam, extraction, or exfoliation. Estheticians should monitor the degree and duration of erythema and adjust technique for clients with sensitive or reactive skin." },
  { id: 359, question: "Which best explains why a broad-spectrum sunscreen is recommended as part of daily skin care, even on cloudy days?", question_es: "¿Cuál explica mejor por qué se recomienda un protector solar de amplio espectro como parte del cuidado diario de la piel, incluso en días nublados?", options: ["UVA rays, which contribute to premature aging and can penetrate clouds and glass, are present throughout daylight hours regardless of visible cloud cover, while UVB rays cause burning; broad-spectrum products protect against both", "Sunscreen is only necessary on sunny days because UV rays cannot penetrate cloud cover at all", "Broad-spectrum sunscreen replaces the need for moisturizer and other skin care steps", "Cloudy-day sun exposure only affects the eyes, not the skin, so facial sunscreen is unnecessary in cloudy conditions"], options_es: ["Los rayos UVA, que contribuyen al envejecimiento prematuro y pueden penetrar las nubes y el vidrio, están presentes durante todas las horas de luz del día independientemente de la cobertura de nubes visible, mientras que los rayos UVB causan quemaduras; los productos de amplio espectro protegen contra ambos", "El protector solar solo es necesario en días soleados porque los rayos UV no pueden penetrar la cobertura de nubes en absoluto", "El protector solar de amplio espectro reemplaza la necesidad de humectante y otros pasos del cuidado de la piel", "La exposición al sol en días nublados solo afecta los ojos, no la piel, por lo que el protector solar facial es innecesario en condiciones nubladas"], correct: 0, explanation: "UVA rays remain fairly constant throughout the day and year, penetrate clouds and glass, and are primarily responsible for photoaging (wrinkles, loss of elasticity) and contribute to skin cancer risk. UVB rays primarily cause sunburn and vary more with weather and season. Because UVA exposure continues even when it's cloudy, broad-spectrum (UVA + UVB) protection is recommended daily." },
  { id: 360, question: "A client with oily, acne-prone skin asks whether they should skip moisturizer entirely. The most appropriate professional response is:", question_es: "Un cliente con piel grasa y propensa al acné pregunta si debe omitir el humectante por completo. La respuesta profesional más apropiada es:", options: ["No — even oily skin needs hydration; recommend a lightweight, oil-free, non-comedogenic moisturizer, since skipping moisturizer can cause the skin to compensate by producing even more oil", "Yes — oily skin never benefits from moisturizer under any circumstances", "Yes — moisturizer should be replaced entirely with astringent toner for oily, acne-prone skin", "No — but only heavy, oil-based creams should be used on oily skin to balance sebum production"], options_es: ["No — incluso la piel grasa necesita hidratación; recomendar un humectante ligero, libre de aceite y no comedogénico, ya que omitir el humectante puede hacer que la piel compense produciendo aún más aceite", "Sí — la piel grasa nunca se beneficia del humectante bajo ninguna circunstancia", "Sí — el humectante debe reemplazarse completamente por tónico astringente para piel grasa y propensa al acné", "No — pero solo deben usarse cremas pesadas a base de aceite en piel grasa para equilibrar la producción de sebo"], correct: 0, explanation: "Oily skin still requires hydration (water), which is different from oil (sebum). Skipping moisturizer can lead to compensatory overproduction of sebum and a compromised moisture barrier. The appropriate recommendation is a lightweight, oil-free, non-comedogenic moisturizer that hydrates without clogging pores or adding excess oil." },
  { id: 361, question: "Comedogenic, as used in skin care product selection, describes:", question_es: "Comedogénico, tal como se usa en la selección de productos para el cuidado de la piel, describe:", options: ["A tendency of an ingredient or product to clog pores and contribute to the formation of comedones (blackheads/whiteheads)", "A property that allows a product to dissolve excess oil from deep within the pore", "An ingredient classification indicating high sun protection factor", "A term describing products specifically formulated to reduce inflammation"], options_es: ["Una tendencia de un ingrediente o producto a obstruir los poros y contribuir a la formación de comedones (puntos negros/blancos)", "Una propiedad que permite a un producto disolver el exceso de aceite desde lo profundo del poro", "Una clasificación de ingredientes que indica un alto factor de protección solar", "Un término que describe productos formulados específicamente para reducir la inflamación"], correct: 0, explanation: "Comedogenic ingredients or products have a tendency to clog pores, potentially leading to comedone formation (blackheads and whiteheads) and breakouts. Estheticians working with acne-prone or oily clients should select non-comedogenic products to minimize the risk of pore blockage and breakouts." },
  { id: 362, question: "Which of the following best describes the role of antioxidants in skin care products?", question_es: "¿Cuál de las siguientes describe mejor el papel de los antioxidantes en los productos para el cuidado de la piel?", options: ["They help neutralize free radicals generated by UV exposure, pollution, and normal metabolic processes, reducing oxidative damage that contributes to premature skin aging", "They permanently remove all existing wrinkles and fine lines from the skin", "They function primarily as physical exfoliants to remove dead skin cells", "They replace the need for sun protection by blocking UV rays directly"], options_es: ["Ayudan a neutralizar los radicales libres generados por la exposición UV, la contaminación y los procesos metabólicos normales, reduciendo el daño oxidativo que contribuye al envejecimiento prematuro de la piel", "Eliminan permanentemente todas las arrugas y líneas finas existentes de la piel", "Funcionan principalmente como exfoliantes físicos para eliminar las células muertas de la piel", "Reemplazan la necesidad de protección solar al bloquear directamente los rayos UV"], correct: 0, explanation: "Antioxidants (such as vitamin C, vitamin E, green tea extract, and resveratrol) help neutralize unstable molecules called free radicals, which are generated by UV exposure, pollution, and normal cellular processes. By reducing oxidative stress, antioxidants help slow visible signs of premature aging, but they do not replace sunscreen or function as exfoliants." },
  { id: 363, question: "A client mentions they have eczema (atopic dermatitis) on their cheeks. The most appropriate esthetic approach is to:", question_es: "Un cliente menciona que tiene eccema (dermatitis atópica) en las mejillas. El enfoque estético más apropiado es:", options: ["Avoid harsh products, fragrances, and aggressive exfoliation on affected areas, use gentle, soothing, fragrance-free products, and refer to a dermatologist for any active or worsening flare-ups, as eczema is a medical skin condition outside the esthetician's scope to treat", "Perform aggressive exfoliation on the affected areas to speed healing", "Apply strong fragranced products to mask any visible redness or irritation", "Diagnose the exact type and severity of the eczema and prescribe a treatment plan with topical steroids"], options_es: ["Evitar productos agresivos, fragancias y exfoliación agresiva en las áreas afectadas, usar productos suaves, calmantes y libres de fragancia, y derivar a un dermatólogo para cualquier brote activo o que empeore, ya que el eccema es una condición médica de la piel fuera del alcance del esteticista para tratar", "Realizar una exfoliación agresiva en las áreas afectadas para acelerar la curación", "Aplicar productos fuertemente perfumados para enmascarar cualquier enrojecimiento o irritación visible", "Diagnosticar el tipo y gravedad exactos del eccema y prescribir un plan de tratamiento con esteroides tópicos"], correct: 0, explanation: "Eczema (atopic dermatitis) is a medical condition outside an esthetician's scope to diagnose or treat. The professional approach is to use gentle, fragrance-free, non-irritating products, avoid aggressive exfoliation or stimulation on affected areas, and refer the client to a dermatologist for diagnosis, treatment, or active flare management." },
  { id: 364, question: "What is the primary function of the skin's lipid (intercellular) barrier within the stratum corneum?", question_es: "¿Cuál es la función principal de la barrera lipídica (intercelular) de la piel dentro del estrato córneo?", options: ["It binds corneocytes together and helps prevent transepidermal water loss while blocking the entry of irritants and pathogens, functioning like 'mortar' between the 'bricks' of skin cells", "It produces melanin to protect the skin from UV radiation", "It generates new skin cells to replace those that are shed", "It regulates body temperature through sweat production"], options_es: ["Une las corneocitos y ayuda a prevenir la pérdida de agua transepidérmica mientras bloquea la entrada de irritantes y patógenos, funcionando como 'mortero' entre los 'ladrillos' de las células de la piel", "Produce melanina para proteger la piel de la radiación UV", "Genera nuevas células de la piel para reemplazar las que se desprenden", "Regula la temperatura corporal a través de la producción de sudor"], correct: 0, explanation: "The lipid barrier, composed of ceramides, cholesterol, and fatty acids, fills the spaces between corneocytes in the stratum corneum — often described using the 'bricks and mortar' model, where corneocytes are the bricks and lipids are the mortar. This barrier helps retain moisture, prevent transepidermal water loss, and block irritants, allergens, and pathogens from penetrating the skin." },
  { id: 365, question: "Why is patch testing recommended before applying a new product or performing a chemical treatment on a client's full face?", question_es: "¿Por qué se recomienda realizar una prueba de parche antes de aplicar un nuevo producto o realizar un tratamiento químico en toda la cara de un cliente?", options: ["It allows the esthetician to observe the skin's reaction to the product on a small area first, helping identify possible allergies, sensitivities, or adverse reactions before broader application reduces risk of a widespread reaction", "It permanently conditions the skin to tolerate any future products without reaction", "It eliminates the need to review a client's intake form or health history", "It guarantees that no allergic reaction can occur during the full treatment"], options_es: ["Permite al esteticista observar la reacción de la piel al producto en un área pequeña primero, ayudando a identificar posibles alergias, sensibilidades o reacciones adversas antes de que la aplicación más amplia reduzca el riesgo de una reacción generalizada", "Condiciona permanentemente la piel para tolerar cualquier producto futuro sin reacción", "Elimina la necesidad de revisar el formulario de admisión o el historial de salud del cliente", "Garantiza que no pueda ocurrir ninguna reacción alérgica durante el tratamiento completo"], correct: 0, explanation: "A patch test involves applying a small amount of product to a discreet area of skin (such as behind the ear or on the inner forearm) and observing for a period of time for signs of irritation, redness, itching, or other adverse reactions. This helps identify potential sensitivities before full-face application, reducing the risk of a widespread negative reaction — though it does not guarantee zero risk and does not replace a thorough client health history review." },
  { id: 366, question: "Which best describes the difference between exfoliation and desquamation?", question_es: "¿Cuál describe mejor la diferencia entre exfoliación y descamación?", options: ["Desquamation is the body's natural shedding of dead skin cells from the stratum corneum, while exfoliation refers to the deliberate removal of dead skin cells through mechanical or chemical means to assist or accelerate that natural process", "Desquamation only occurs through professional chemical peels, while exfoliation only happens naturally without any product or technique", "Exfoliation is a disease process, while desquamation is a healthy process — the two are unrelated", "Desquamation refers only to hair shedding, while exfoliation refers only to skin cell shedding"], options_es: ["La descamación es el desprendimiento natural del cuerpo de las células muertas de la piel del estrato córneo, mientras que la exfoliación se refiere a la eliminación deliberada de células muertas de la piel a través de medios mecánicos o químicos para ayudar o acelerar ese proceso natural", "La descamación solo ocurre a través de peelings químicos profesionales, mientras que la exfoliación solo ocurre naturalmente sin ningún producto o técnica", "La exfoliación es un proceso de enfermedad, mientras que la descamación es un proceso saludable — los dos no están relacionados", "La descamación se refiere solo a la caída del cabello, mientras que la exfoliación se refiere solo al desprendimiento de células de la piel"], correct: 0, explanation: "Desquamation is the natural, ongoing shedding of dead corneocytes from the surface of the skin as part of the skin's renewal cycle. Exfoliation is the deliberate, professional or at-home process — using mechanical methods (scrubs, brushes) or chemical methods (AHAs, BHAs, enzymes) — to remove built-up dead skin cells and support or speed the natural desquamation process." },
  { id: 367, question: "A client's intake form notes they are using a prescription retinoid (such as tretinoin) at home. Before performing an exfoliating facial treatment, the esthetician should:", question_es: "El formulario de admisión de un cliente indica que está usando un retinoide recetado (como la tretinoína) en casa. Antes de realizar un tratamiento facial exfoliante, el esteticista debe:", options: ["Ask about frequency of use and recent application, and consider modifying or postponing aggressive exfoliation, since retinoids increase skin sensitivity and the combination with additional exfoliation raises the risk of irritation, redness, or compromised barrier function", "Proceed with the most aggressive exfoliation available, since retinoid use means the skin can tolerate more intense treatments", "Disregard the information, since prescription products have no bearing on in-spa treatment planning", "Instruct the client to stop using their prescription retinoid permanently before any future spa visits"], options_es: ["Preguntar sobre la frecuencia de uso y la aplicación reciente, y considerar modificar o posponer la exfoliación agresiva, ya que los retinoides aumentan la sensibilidad de la piel y la combinación con exfoliación adicional eleva el riesgo de irritación, enrojecimiento o función de barrera comprometida", "Proceder con la exfoliación más agresiva disponible, ya que el uso de retinoides significa que la piel puede tolerar tratamientos más intensos", "Ignorar la información, ya que los productos recetados no tienen relación con la planificación del tratamiento en el spa", "Indicar al cliente que deje de usar su retinoide recetado de forma permanente antes de cualquier futura visita al spa"], correct: 0, explanation: "Retinoids increase cell turnover and can make skin more sensitive, thinner-feeling, and prone to irritation. Combining retinoid use with additional exfoliation (mechanical or chemical) significantly raises the risk of redness, irritation, peeling, or barrier disruption. The esthetician should always review intake information, ask about current use, and adjust the treatment plan — selecting gentler options or rescheduling more aggressive exfoliation — rather than stopping a client's prescribed regimen, which is outside their scope." },
]

const FT = [
  { id: 368, question: "The first step of a basic facial treatment, after the client is properly draped and positioned, is typically:", question_es: "El primer paso de un tratamiento facial básico, después de que el cliente esté correctamente cubierto y posicionado, es típicamente:", options: ["Cleansing — to remove makeup, surface oils, and debris and prepare the skin for analysis and subsequent steps", "Extraction — to clear all visible congestion before any other product is applied", "Application of a chemical peel — to maximize product penetration from the start", "Facial massage — to relax the client before any products are applied"], options_es: ["Limpieza — para eliminar el maquillaje, los aceites superficiales y la suciedad y preparar la piel para el análisis y los pasos posteriores", "Extracción — para eliminar toda la congestión visible antes de aplicar cualquier otro producto", "Aplicación de un peeling químico — para maximizar la penetración del producto desde el principio", "Masaje facial — para relajar al cliente antes de aplicar cualquier producto"], correct: 0, explanation: "Cleansing is the foundational first step of a facial. It removes makeup, surface oil, sweat, and debris, allowing the esthetician to accurately analyze the skin and ensuring that subsequent products (toners, exfoliants, masks, serums) can be applied to clean skin and absorb effectively." },
  { id: 369, question: "Why is skin analysis performed early in a facial treatment, typically right after cleansing?", question_es: "¿Por qué se realiza el análisis de la piel temprano en un tratamiento facial, típicamente justo después de la limpieza?", options: ["It allows the esthetician to accurately assess skin type, conditions, and concerns on clean skin so the treatment plan and products can be customized appropriately for that client", "It is required so the esthetician can determine the exact price of the service before continuing", "It replaces the need for a written client intake or consultation form", "It allows the esthetician to apply makeup correctly at the end of the service"], options_es: ["Permite al esteticista evaluar con precisión el tipo de piel, las condiciones y las preocupaciones en piel limpia para que el plan de tratamiento y los productos puedan personalizarse adecuadamente para ese cliente", "Es necesario para que el esteticista determine el precio exacto del servicio antes de continuar", "Reemplaza la necesidad de un formulario de admisión o consulta escrito del cliente", "Permite al esteticista aplicar maquillaje correctamente al final del servicio"], correct: 0, explanation: "Skin analysis performed on freshly cleansed skin (often using magnification) allows the esthetician to accurately observe pore size, texture, hydration level, pigmentation, breakouts, and other conditions without makeup or surface debris obscuring the assessment — enabling a tailored, effective treatment plan and product selection." },
  { id: 370, question: "Steaming the face during a facial treatment primarily serves to:", question_es: "El vapor facial durante un tratamiento facial sirve principalmente para:", options: ["Soften the skin's surface and loosen debris within follicles, making extractions easier and helping subsequent products absorb more effectively", "Permanently close pores and prevent any future breakouts", "Replace the need for cleansing prior to extractions", "Sterilize the skin's surface, eliminating the need for sanitized implements"], options_es: ["Suavizar la superficie de la piel y aflojar la suciedad dentro de los folículos, facilitando las extracciones y ayudando a que los productos posteriores se absorban más eficazmente", "Cerrar permanentemente los poros y prevenir cualquier brote futuro", "Reemplazar la necesidad de limpieza antes de las extracciones", "Esterilizar la superficie de la piel, eliminando la necesidad de implementos desinfectados"], correct: 0, explanation: "Steam softens the surface of the skin and helps loosen sebum, debris, and dead skin cells within follicles, making extractions gentler and more effective. It can also enhance the penetration and absorption of subsequent treatment products. Steam should be used cautiously (proper distance and duration) to avoid overheating sensitive or couperose skin." },
  { id: 371, question: "When should facial steaming be avoided or modified for a client?", question_es: "¿Cuándo se debe evitar o modificar el vapor facial para un cliente?", options: ["When the client has couperose or highly sensitive/reactive skin, asthma or breathing difficulties, or open lesions, as heat and moisture can aggravate these conditions", "When the client has normal, balanced skin with no particular concerns", "When the client requests a deeply relaxing experience as part of their service", "When the esthetician is performing a basic cleansing-only service with no extractions planned"], options_es: ["Cuando el cliente tiene piel con cuperosis o muy sensible/reactiva, asma o dificultades respiratorias, o lesiones abiertas, ya que el calor y la humedad pueden agravar estas condiciones", "Cuando el cliente tiene piel normal y equilibrada sin preocupaciones particulares", "Cuando el cliente solicita una experiencia profundamente relajante como parte de su servicio", "Cuando el esteticista está realizando un servicio de solo limpieza básica sin extracciones planificadas"], correct: 0, explanation: "Steam can aggravate couperose or highly reactive/sensitive skin by increasing redness and irritation, can be uncomfortable or risky for clients with respiratory conditions like asthma, and should never be directed at open lesions or active infections. The esthetician should modify or omit steam and use alternative methods (warm towels at safe temperatures, hydrating mists) for these clients." },
  { id: 372, question: "Manual extraction during a facial treatment should be performed:", question_es: "La extracción manual durante un tratamiento facial debe realizarse:", options: ["Using clean, gloved hands or sanitized tools, with gentle, controlled pressure, only on follicles that are sufficiently softened and accessible, and stopped if the area becomes overly red, irritated, or the material does not release easily", "With maximum pressure to ensure all visible congestion is removed in a single pass", "Without gloves, since direct skin-to-skin contact improves the technician's control over the procedure", "On any lesion present on the skin, including pustules, cysts, and inflamed acne, regardless of depth or size"], options_es: ["Usando manos limpias y enguantadas o herramientas desinfectadas, con presión suave y controlada, solo en folículos que estén suficientemente ablandados y accesibles, y deteniéndose si el área se enrojece o irrita en exceso, o si el material no se libera fácilmente", "Con presión máxima para asegurar que toda la congestión visible se elimine en un solo paso", "Sin guantes, ya que el contacto directo piel a piel mejora el control del técnico sobre el procedimiento", "En cualquier lesión presente en la piel, incluyendo pústulas, quistes y acné inflamado, sin importar la profundidad o el tamaño"], correct: 0, explanation: "Proper extraction technique requires gloved hands and/or sanitized tools, gentle and controlled pressure, and should be limited to follicles that are accessible and ready to be cleared. The esthetician must stop if the skin becomes excessively red, irritated, or if material does not release easily — continuing risks tissue damage, bruising, and infection. Deep cysts, nodules, and significantly inflamed acne are outside the scope of esthetic extraction and should be referred to a dermatologist." },
  { id: 373, question: "Which best explains the purpose of facial massage within a treatment service?", question_es: "¿Cuál explica mejor el propósito del masaje facial dentro de un servicio de tratamiento?", options: ["It can promote relaxation, stimulate circulation, support lymphatic flow, and enhance the overall sensory experience of the treatment when performed with appropriate technique and pressure for the client's skin condition", "It permanently changes the structure of facial muscles to reduce the appearance of wrinkles", "It is required to physically force product ingredients through the dermis into the bloodstream", "It replaces the need for cleansing and product application in a basic facial"], options_es: ["Puede promover la relajación, estimular la circulación, apoyar el flujo linfático y mejorar la experiencia sensorial general del tratamiento cuando se realiza con la técnica y presión apropiadas para la condición de la piel del cliente", "Cambia permanentemente la estructura de los músculos faciales para reducir la apariencia de las arrugas", "Es necesario para forzar físicamente los ingredientes del producto a través de la dermis hacia el torrente sanguíneo", "Reemplaza la necesidad de limpieza y aplicación de productos en un facial básico"], correct: 0, explanation: "Facial massage, when performed with techniques and pressure appropriate to the client's skin type and condition, can enhance relaxation, support blood circulation and lymphatic flow, and add to the overall pleasurable experience of the service. It is a complementary technique — not a substitute for cleansing, analysis, or appropriate product application — and should be modified or avoided for certain conditions (e.g., active infection, certain medical contraindications)." },
  { id: 374, question: "A facial mask formulated with clay or kaolin is generally chosen for clients with:", question_es: "Una mascarilla facial formulada con arcilla o caolín generalmente se elige para clientes con:", options: ["Oily or congested skin, since these masks help absorb excess oil, draw out impurities, and have a mattifying, purifying effect", "Extremely dry, flaky, dehydrated skin that needs intensive hydration above all else", "Highly sensitive, reactive, or couperose skin that requires the gentlest possible formulations", "Active open wounds, sunburn, or compromised skin barrier needing soothing repair"], options_es: ["Piel grasa o congestionada, ya que estas mascarillas ayudan a absorber el exceso de aceite, extraer impurezas y tienen un efecto matificante y purificante", "Piel extremadamente seca, escamosa y deshidratada que necesita hidratación intensiva sobre todo lo demás", "Piel altamente sensible, reactiva o con cuperosis que requiere las formulaciones más suaves posibles", "Heridas abiertas activas, quemaduras solares o barrera cutánea comprometida que necesita reparación calmante"], correct: 0, explanation: "Clay and kaolin-based masks have absorbent, oil-controlling, and purifying properties, making them well suited for oily or congested skin types. They can be drying, so they are generally not recommended for extremely dry, dehydrated, sensitive, couperose, or compromised skin, where hydrating, soothing formulations are more appropriate." },
  { id: 375, question: "Why is it important to apply products in the correct order during a facial treatment (for example, thinner/lighter consistency products before thicker, heavier ones)?", question_es: "¿Por qué es importante aplicar los productos en el orden correcto durante un tratamiento facial (por ejemplo, productos de consistencia más ligera antes que los más pesados)?", options: ["It allows lighter products to absorb into the skin first without being blocked by heavier occlusive products, helping each product perform its intended function effectively", "It has no real effect on product performance — order is purely a matter of esthetician preference", "It ensures that the most expensive products are always applied closest to the skin", "It guarantees that no product will ever cause an allergic reaction"], options_es: ["Permite que los productos más ligeros se absorban en la piel primero sin ser bloqueados por productos oclusivos más pesados, ayudando a que cada producto cumpla su función prevista de manera efectiva", "No tiene ningún efecto real en el rendimiento del producto — el orden es puramente una cuestión de preferencia del esteticista", "Garantiza que los productos más costosos siempre se apliquen más cerca de la piel", "Garantiza que ningún producto causará jamás una reacción alérgica"], correct: 0, explanation: "Applying products from thinnest/lightest to thickest/heaviest consistency (e.g., toners and serums before creams and occlusive moisturizers) helps ensure that lighter-weight, often active-ingredient products can penetrate and perform their function rather than being blocked by a heavier barrier layer applied first. This sequencing helps maximize the effectiveness of each product." },
  { id: 376, question: "A high-frequency device used in facial treatments produces a mild thermal and germicidal effect primarily through:", question_es: "Un dispositivo de alta frecuencia utilizado en tratamientos faciales produce un efecto térmico y germicida leve principalmente a través de:", options: ["A gentle oscillating electrical current passed through a glass electrode that creates a mild warming and germicidal (ozone-producing) effect on the skin's surface", "Direct injection of active ingredients into the dermis using a fine needle array", "Application of intense heat exceeding 150°F directly onto the epidermis", "Magnetic fields that physically lift and tighten facial muscles"], options_es: ["Una suave corriente eléctrica oscilante que pasa a través de un electrodo de vidrio que crea un efecto leve de calentamiento y germicida (productor de ozono) en la superficie de la piel", "Inyección directa de ingredientes activos en la dermis usando una matriz de agujas finas", "Aplicación de calor intenso que excede los 150°F directamente sobre la epidermis", "Campos magnéticos que levantan y tensan físicamente los músculos faciales"], correct: 0, explanation: "High-frequency devices use a glass electrode through which a gentle, oscillating electrical current passes, producing a mild warming sensation and a germicidal (ozone) effect at the skin's surface. This can help with circulation, soothing certain conditions, and providing an antibacterial benefit, but it does not inject ingredients, apply intense heat, or physically alter facial musculature." },
  { id: 377, question: "Galvanic current used in some facial devices for desincrustation works by:", question_es: "La corriente galvánica utilizada en algunos dispositivos faciales para la desincrustación funciona mediante:", options: ["Using a steady direct current with a specific polarity to create a chemical reaction that helps emulsify and loosen sebum and debris within the follicle, making extraction easier", "Producing intense heat that physically melts away sebum deposits in the follicle", "Generating ultrasonic vibrations that fragment and remove dead skin cells mechanically", "Releasing a controlled burst of high-pressure water to flush out pore contents"], options_es: ["Usar una corriente continua estable con una polaridad específica para crear una reacción química que ayuda a emulsionar y aflojar el sebo y los residuos dentro del folículo, facilitando la extracción", "Producir calor intenso que derrite físicamente los depósitos de sebo en el folículo", "Generar vibraciones ultrasónicas que fragmentan y eliminan mecánicamente las células muertas de la piel", "Liberar una ráfaga controlada de agua a alta presión para eliminar el contenido de los poros"], correct: 0, explanation: "Galvanic current is a steady, direct electrical current. In desincrustation, the current's polarity is used with an appropriate solution to create a chemical reaction (saponification) that helps emulsify and loosen hardened sebum and debris within follicles, softening the material and making extraction gentler and more effective." },
  { id: 378, question: "Which of the following is an appropriate reason to refer a facial client to a dermatologist rather than proceed with a planned esthetic service?", question_es: "¿Cuál de las siguientes es una razón apropiada para derivar a un cliente facial a un dermatólogo en lugar de continuar con el servicio estético planificado?", options: ["The esthetician notices an irregularly shaped, asymmetric, multicolored mole that has reportedly changed in size or appearance recently", "The client has slightly oily skin in the T-zone area", "The client mentions they recently started using a new daily moisturizer", "The client has a small amount of mild redness from sun exposure two days prior"], options_es: ["El esteticista nota un lunar de forma irregular, asimétrico y multicolor que según se informa ha cambiado de tamaño o apariencia recientemente", "El cliente tiene piel ligeramente grasa en el área de la zona T", "El cliente menciona que recientemente comenzó a usar un nuevo humectante diario", "El cliente tiene un poco de enrojecimiento leve por exposición al sol dos días antes"], correct: 0, explanation: "Asymmetry, irregular borders, color variation, and changes over time in a mole are warning signs (consistent with the ABCDE rule for melanoma) that fall well outside an esthetician's scope to evaluate or treat. A professional should tactfully recommend the client see a dermatologist for evaluation rather than proceeding with the planned service over that area, while continuing to provide care for unaffected areas as appropriate." },
  { id: 379, question: "What is the main purpose of using a magnifying lamp during facial treatments?", question_es: "¿Cuál es el propósito principal de usar una lámpara de aumento durante los tratamientos faciales?", options: ["To allow the esthetician to closely examine the skin's surface for conditions, congestion, and texture that may not be visible to the naked eye, supporting accurate analysis and treatment planning", "To sterilize the skin's surface using concentrated light energy", "To permanently brighten and even out skin tone through repeated light exposure", "To replace the need for any verbal consultation with the client"], options_es: ["Permitir al esteticista examinar de cerca la superficie de la piel en busca de condiciones, congestión y textura que pueden no ser visibles a simple vista, apoyando un análisis preciso y la planificación del tratamiento", "Esterilizar la superficie de la piel usando energía luminosa concentrada", "Aclarar y unificar permanentemente el tono de la piel mediante exposición repetida a la luz", "Reemplazar la necesidad de cualquier consulta verbal con el cliente"], correct: 0, explanation: "A magnifying lamp allows the esthetician to closely examine fine details of the skin's surface — such as comedones, texture irregularities, fine lines, and other conditions — that may not be readily visible without magnification. This supports a more thorough and accurate skin analysis, which informs appropriate treatment planning, but it does not sterilize, permanently alter pigmentation, or substitute for client communication." },
  { id: 380, question: "When performing a facial treatment on a client with active, inflamed acne (papules and pustules), the esthetician should:", question_es: "Al realizar un tratamiento facial en un cliente con acné activo e inflamado (pápulas y pústulas), el esteticista debe:", options: ["Use gentle, non-irritating techniques and products suited for acneic skin, avoid aggressive extraction or stimulation of inflamed lesions, and refer to a dermatologist for lesions requiring more advanced medical treatment", "Use the most aggressive extraction technique available to clear all lesions in a single visit", "Apply a heavy, occlusive moisturizing mask directly over all active lesions to seal in moisture", "Avoid the area entirely and refuse to provide any service to the client"], options_es: ["Usar técnicas y productos suaves y no irritantes adecuados para piel acneica, evitar la extracción agresiva o la estimulación de lesiones inflamadas, y derivar a un dermatólogo para las lesiones que requieran tratamiento médico más avanzado", "Usar la técnica de extracción más agresiva disponible para eliminar todas las lesiones en una sola visita", "Aplicar una mascarilla hidratante pesada y oclusiva directamente sobre todas las lesiones activas para sellar la humedad", "Evitar el área por completo y negarse a brindar cualquier servicio al cliente"], correct: 0, explanation: "Inflamed acne lesions (papules, pustules, and especially nodules or cysts) are sensitive and prone to worsening with aggressive manipulation, which can cause scarring, spread bacteria, or increase inflammation. The esthetician should use gentle, appropriate products and techniques, avoid extracting or stimulating inflamed lesions, and refer clients with significant or persistent active acne to a dermatologist for medical-level treatment, while still providing appropriate, modified care within their scope." },
  { id: 381, question: "Why should an esthetician avoid using the same extraction tool on multiple clients without proper sanitation between uses?", question_es: "¿Por qué un esteticista debe evitar usar la misma herramienta de extracción en varios clientes sin una desinfección adecuada entre usos?", options: ["Reusing implements without proper cleaning and disinfection between clients can transfer bacteria, viruses, or other pathogens from one client to another, posing a serious infection control risk", "Extraction tools are designed to be replaced after each individual extraction regardless of client", "Sanitizing tools between clients is only a cosmetic courtesy and has no real effect on client safety", "Extraction tools cannot transmit any pathogens because metal surfaces are naturally antimicrobial"], options_es: ["Reutilizar implementos sin la limpieza y desinfección adecuadas entre clientes puede transferir bacterias, virus u otros patógenos de un cliente a otro, lo que representa un riesgo grave para el control de infecciones", "Las herramientas de extracción están diseñadas para reemplazarse después de cada extracción individual sin importar el cliente", "Desinfectar las herramientas entre clientes es solo una cortesía cosmética y no tiene un efecto real en la seguridad del cliente", "Las herramientas de extracción no pueden transmitir ningún patógeno porque las superficies metálicas son naturalmente antimicrobianas"], correct: 0, explanation: "Extraction tools come into direct contact with skin, blood, and follicular material, creating a real risk of cross-contamination if not properly cleaned and disinfected between each client according to state regulations and manufacturer guidelines. Proper infection control protocols protect both the esthetician and clients from the spread of bacteria, viruses, and other pathogens." },
  { id: 382, question: "A client with rosacea asks for a deep, stimulating facial massage and a hot steam treatment. The most appropriate professional response is to:", question_es: "Un cliente con rosácea pide un masaje facial profundo y estimulante y un tratamiento de vapor caliente. La respuesta profesional más apropiada es:", options: ["Explain that heat and vigorous stimulation can trigger or worsen rosacea flare-ups, and offer a gentler, soothing treatment plan with cooler temperatures and lighter techniques instead", "Provide exactly what the client requested, since client preference always overrides professional judgment about appropriate technique", "Refuse to provide any facial service to a client with rosacea under any circumstances", "Recommend the client increase the heat and pressure even further to desensitize the affected areas over time"], options_es: ["Explicar que el calor y la estimulación vigorosa pueden desencadenar o empeorar los brotes de rosácea, y ofrecer en su lugar un plan de tratamiento más suave y calmante con temperaturas más frescas y técnicas más ligeras", "Proporcionar exactamente lo que el cliente solicitó, ya que la preferencia del cliente siempre anula el juicio profesional sobre la técnica apropiada", "Negarse a proporcionar cualquier servicio facial a un cliente con rosácea bajo cualquier circunstancia", "Recomendar al cliente que aumente aún más el calor y la presión para desensibilizar las áreas afectadas con el tiempo"], correct: 0, explanation: "Heat, steam, and vigorous stimulation are common triggers for rosacea flare-ups, as they promote vasodilation and increased blood flow to already-reactive skin. The professional approach is to educate the client about these triggers and offer a modified treatment plan — using cooler temperatures, gentler techniques, and soothing, non-irritating products — rather than simply complying with a request that could worsen their condition." },
  { id: 383, question: "What is the primary purpose of using cold (cryotherapy) tools, such as a cold roller or chilled globes, at the end of a facial treatment?", question_es: "¿Cuál es el propósito principal de usar herramientas frías (criotherapy), como un rodillo frío o globos refrigerados, al final de un tratamiento facial?", options: ["To help constrict blood vessels, calm inflammation, reduce redness, and provide a refreshing, soothing sensation as the service concludes", "To permanently eliminate all visible pores on the treated area", "To replace the need for sunscreen application after the service", "To deeply exfoliate the surface of the skin through thermal shock"], options_es: ["Ayudar a contraer los vasos sanguíneos, calmar la inflamación, reducir el enrojecimiento y proporcionar una sensación refrescante y calmante al concluir el servicio", "Eliminar permanentemente todos los poros visibles en el área tratada", "Reemplazar la necesidad de aplicar protector solar después del servicio", "Exfoliar profundamente la superficie de la piel mediante choque térmico"], correct: 0, explanation: "Cold tools cause vasoconstriction (narrowing of blood vessels), which can help reduce redness and inflammation, calm the skin after stimulating procedures like extraction or massage, and leave the client with a refreshed, soothing sensation. They do not permanently change pore size, exfoliate through thermal shock, or substitute for daily sun protection." },
  { id: 384, question: "Before beginning any facial treatment, reviewing the client's intake/consultation form is important primarily because it helps the esthetician:", question_es: "Antes de comenzar cualquier tratamiento facial, revisar el formulario de admisión/consulta del cliente es importante principalmente porque ayuda al esteticista a:", options: ["Identify allergies, medications, medical conditions, and concerns that may affect product selection, technique, and overall treatment safety", "Determine the exact retail price the client should be charged for additional products", "Decide which social media platform to use when promoting the service afterward", "Skip the need for an in-person skin analysis altogether"], options_es: ["Identificar alergias, medicamentos, condiciones médicas e inquietudes que puedan afectar la selección de productos, la técnica y la seguridad general del tratamiento", "Determinar el precio exacto de venta al por menor que se debe cobrar al cliente por productos adicionales", "Decidir qué plataforma de redes sociales usar para promocionar el servicio después", "Omitir por completo la necesidad de un análisis de piel en persona"], correct: 0, explanation: "The intake/consultation form provides essential information about allergies, medications, skin conditions, and client concerns or goals. Reviewing it before beginning the service allows the esthetician to make informed decisions about which products and techniques are safe and appropriate, helping prevent adverse reactions and tailor the treatment to the client's needs — it does not replace the in-person skin analysis but works together with it." },
  { id: 385, question: "Which scenario represents an appropriate modification of a facial treatment based on a client's stated medical condition?", question_es: "¿Cuál escenario representa una modificación apropiada de un tratamiento facial basada en la condición médica declarada de un cliente?", options: ["A client mentions they have recently undergone surgery on the treatment area, so the esthetician postpones any stimulating techniques on that area and consults the intake information and, where appropriate, the client's aftercare guidance before proceeding", "A client mentions a minor seasonal cold, so the esthetician cancels the appointment entirely and refuses to reschedule", "A client mentions they take a daily multivitamin, so the esthetician declines to perform any facial service whatsoever", "A client mentions mild seasonal allergies, so the esthetician decides to perform an aggressive chemical exfoliation treatment instead of the planned basic facial"], options_es: ["Un cliente menciona que se sometió recientemente a una cirugía en el área de tratamiento, por lo que el esteticista pospone cualquier técnica estimulante en esa área y consulta la información de admisión y, cuando corresponda, las indicaciones de cuidado posterior del cliente antes de continuar", "Un cliente menciona un resfriado leve estacional, por lo que el esteticista cancela la cita por completo y se niega a reprogramarla", "Un cliente menciona que toma una multivitamina diaria, por lo que el esteticista se niega a realizar cualquier servicio facial", "Un cliente menciona alergias estacionales leves, por lo que el esteticista decide realizar un tratamiento de exfoliación química agresivo en lugar del facial básico planeado"], correct: 0, explanation: "Thoughtful modification means adjusting the plan based on relevant information — for example, avoiding stimulation over a recent surgical site and reviewing any restrictions before proceeding — rather than either ignoring the information or overreacting by canceling or escalating the service unnecessarily. Recognizing what is and is not relevant to the planned treatment is part of sound professional judgment." },
  { id: 386, question: "Which best describes the difference between a basic (European) facial and a specialized treatment facial (such as an anti-aging or acne-focused facial)?", question_es: "¿Cuál describe mejor la diferencia entre un facial básico (europeo) y un facial de tratamiento especializado (como un facial antienvejecimiento o enfocado en el acné)?", options: ["A basic facial follows a general sequence (cleansing, analysis, exfoliation, extraction, massage, mask, finishing products) suitable for most skin types, while a specialized facial customizes products, techniques, and devices to target a specific concern in greater depth", "A basic facial never includes cleansing, while a specialized facial always begins with cleansing", "A basic facial is performed only on clients under 18, while specialized facials are reserved for adult clients", "A basic facial requires advanced medical licensure, while specialized facials can be performed without any license"], options_es: ["Un facial básico sigue una secuencia general (limpieza, análisis, exfoliación, extracción, masaje, mascarilla, productos finales) adecuada para la mayoría de los tipos de piel, mientras que un facial especializado personaliza productos, técnicas y dispositivos para abordar una preocupación específica con mayor profundidad", "Un facial básico nunca incluye limpieza, mientras que un facial especializado siempre comienza con limpieza", "Un facial básico se realiza solo en clientes menores de 18 años, mientras que los faciales especializados están reservados para clientes adultos", "Un facial básico requiere licencia médica avanzada, mientras que los faciales especializados pueden realizarse sin ninguna licencia"], correct: 0, explanation: "A basic facial follows a general, broadly applicable sequence of steps designed to cleanse, analyze, and care for the skin. A specialized treatment facial builds on that foundation but tailors products, techniques, devices, and focus areas to address a specific concern (such as aging, acne, or hyperpigmentation) in greater depth, often incorporating targeted ingredients or modalities appropriate to that concern." },
  { id: 387, question: "What is an appropriate way for an esthetician to address a client's unrealistic expectations about the results of a single facial treatment (for example, expecting permanent wrinkle removal)?", question_es: "¿Cuál es una manera apropiada para que un esteticista aborde las expectativas poco realistas de un cliente sobre los resultados de un solo tratamiento facial (por ejemplo, esperar la eliminación permanente de las arrugas)?", options: ["Tactfully and honestly explain what the treatment can realistically achieve, describe the likely timeline and the value of consistent care, and avoid promising outcomes that are outside the scope or capability of the service", "Agree with the client's expectations to avoid an uncomfortable conversation, even if those expectations cannot be met", "Avoid discussing expected outcomes altogether so the client can form their own conclusions afterward", "Promise that the single treatment will produce permanent results in order to maintain client satisfaction"], options_es: ["Explicar de manera honesta y con tacto lo que el tratamiento puede lograr de manera realista, describir el cronograma probable y el valor de un cuidado constante, y evitar prometer resultados que estén fuera del alcance o la capacidad del servicio", "Estar de acuerdo con las expectativas del cliente para evitar una conversación incómoda, aunque esas expectativas no puedan cumplirse", "Evitar discutir los resultados esperados por completo para que el cliente saque sus propias conclusiones después", "Prometer que el tratamiento único producirá resultados permanentes para mantener la satisfacción del cliente"], correct: 0, explanation: "Professional communication includes setting realistic expectations. The esthetician should clearly and respectfully explain what a treatment can and cannot achieve, the realistic timeline for visible improvement, and the importance of an ongoing skin care routine and series of treatments for lasting results — never promising permanent or guaranteed outcomes that the service cannot deliver." },
  { id: 388, question: "A client states they are currently undergoing chemotherapy treatment for cancer. Regarding facial services, the esthetician should:", question_es: "Un cliente indica que actualmente está en tratamiento de quimioterapia para el cáncer. En cuanto a los servicios faciales, el esteticista debe:", options: ["Consult available guidance (and the client's medical team where appropriate), and modify the treatment significantly — using extra-gentle techniques, avoiding stimulating products and procedures, and being especially mindful of heightened skin sensitivity and immune considerations", "Proceed with the standard facial exactly as it would be performed for any other client", "Refuse to provide service of any kind to a client undergoing cancer treatment", "Recommend the client discontinue their chemotherapy regimen in order to receive more intensive spa services"], options_es: ["Consultar la orientación disponible (y al equipo médico del cliente cuando corresponda), y modificar significativamente el tratamiento — usando técnicas extra suaves, evitando productos y procedimientos estimulantes, y siendo especialmente consciente de la mayor sensibilidad de la piel y las consideraciones inmunológicas", "Proceder con el facial estándar exactamente como se realizaría para cualquier otro cliente", "Negarse a brindar cualquier tipo de servicio a un cliente que está en tratamiento contra el cáncer", "Recomendar al cliente que interrumpa su régimen de quimioterapia para recibir servicios de spa más intensivos"], correct: 0, explanation: "Clients undergoing chemotherapy often experience heightened skin sensitivity, dryness, and immune system changes. While many can safely receive modified, gentle services (and some estheticians pursue specialized oncology esthetics training), the appropriate approach is to gather thorough information, consult available professional guidance, and significantly modify the treatment — never providing a standard intensive service or making medical recommendations about their treatment regimen, which is entirely outside the esthetician's scope." },
  { id: 389, question: "Which statement best reflects appropriate draping and positioning practices for facial treatments?", question_es: "¿Cuál afirmación refleja mejor las prácticas apropiadas de cobertura y posicionamiento para los tratamientos faciales?", options: ["The client should be properly draped to maintain modesty and comfort, with hair secured away from the face and clothing protected, and positioned in a way that supports both client comfort and the esthetician's ergonomics and access to the treatment area", "Draping is optional and only used for clients who specifically request it", "The client's hair should always remain loose and uncovered to allow full access to the hairline at all times", "Positioning the client is solely about achieving the most dramatic 'before and after' photographs"], options_es: ["El cliente debe estar correctamente cubierto para mantener el pudor y la comodidad, con el cabello asegurado lejos del rostro y la ropa protegida, y posicionado de una manera que apoye tanto la comodidad del cliente como la ergonomía y el acceso del esteticista al área de tratamiento", "La cobertura es opcional y solo se usa para clientes que la soliciten específicamente", "El cabello del cliente siempre debe permanecer suelto y descubierto para permitir el acceso completo a la línea del cabello en todo momento", "Posicionar al cliente se trata únicamente de lograr las fotografías de 'antes y después' más dramáticas"], correct: 0, explanation: "Proper draping protects the client's clothing, maintains their comfort and sense of modesty, and contributes to a professional, sanitary service environment. Securing hair away from the face (with a headband or cap) protects both the hair and allows full access to the treatment area. Thoughtful positioning supports client comfort throughout the service as well as the esthetician's ability to work safely and effectively." },
  { id: 390, question: "Why is it important for an esthetician to maintain proper body mechanics (posture, positioning, and movement) while performing facial treatments?", question_es: "¿Por qué es importante que un esteticista mantenga una mecánica corporal adecuada (postura, posicionamiento y movimiento) mientras realiza tratamientos faciales?", options: ["It helps prevent repetitive strain injuries and chronic musculoskeletal problems for the esthetician over a career of providing hands-on services, while also supporting more controlled, effective technique", "It is required so that the client can clearly see the esthetician's technique throughout the service", "It guarantees that the treatment will produce faster visible results for the client", "It eliminates the need for breaks or rest periods throughout a full day of services"], options_es: ["Ayuda a prevenir lesiones por esfuerzo repetitivo y problemas musculoesqueléticos crónicos para el esteticista a lo largo de una carrera brindando servicios prácticos, al mismo tiempo que favorece una técnica más controlada y efectiva", "Es necesario para que el cliente pueda ver claramente la técnica del esteticista durante todo el servicio", "Garantiza que el tratamiento producirá resultados visibles más rápidos para el cliente", "Elimina la necesidad de descansos o períodos de descanso durante un día completo de servicios"], correct: 0, explanation: "Estheticians perform repetitive hands-on movements throughout their careers, which can lead to strain injuries (such as in the wrists, shoulders, neck, and back) if proper body mechanics are not used. Maintaining good posture, an ergonomic treatment room setup, and controlled movement helps prevent chronic injury, supports longevity in the profession, and contributes to smoother, more controlled technique." },
  { id: 391, question: "A client asks the esthetician to recommend a specific over-the-counter medication to treat their persistent cystic acne. The most appropriate response is to:", question_es: "Un cliente le pide al esteticista que recomiende un medicamento específico de venta libre para tratar su acné quístico persistente. La respuesta más apropiada es:", options: ["Explain that recommending or prescribing medication is outside the scope of esthetic practice, and suggest the client consult a dermatologist or physician for appropriate medical evaluation and treatment options", "Recommend the strongest available over-the-counter acne medication regardless of the client's skin type or sensitivities", "Suggest the client simply increase the frequency of their facial treatments instead of seeking any medical guidance", "Provide a confident diagnosis of the underlying hormonal cause and suggest a treatment plan accordingly"], options_es: ["Explicar que recomendar o recetar medicamentos está fuera del alcance de la práctica estética, y sugerir que el cliente consulte a un dermatólogo o médico para una evaluación médica adecuada y opciones de tratamiento", "Recomendar el medicamento contra el acné de venta libre más fuerte disponible sin importar el tipo de piel o las sensibilidades del cliente", "Sugerir que el cliente simplemente aumente la frecuencia de sus tratamientos faciales en lugar de buscar orientación médica", "Proporcionar un diagnóstico seguro de la causa hormonal subyacente y sugerir un plan de tratamiento en consecuencia"], correct: 0, explanation: "Recommending, diagnosing, or prescribing medication — even over-the-counter products for a specific medical condition — falls outside the legal scope of esthetic practice. Persistent cystic acne often has underlying causes that require medical evaluation. The appropriate professional response is to acknowledge the concern, explain the limits of esthetic practice, and refer the client to a dermatologist or physician." },
  { id: 392, question: "Which of these is an appropriate way to incorporate aromatherapy (essential oils) into a facial treatment?", question_es: "¿Cuál de estas es una manera apropiada de incorporar la aromaterapia (aceites esenciales) en un tratamiento facial?", options: ["Use properly diluted, professionally appropriate products, after confirming the client has no known allergies or sensitivities and no contraindicating conditions (such as pregnancy, for certain oils), and discontinue use if any irritation occurs", "Apply concentrated, undiluted essential oils directly to the client's skin to maximize their effect", "Use any essential oil on any client, since essential oils cannot cause allergic reactions or skin irritation", "Substitute essential oils for all standard facial products, since aromatherapy alone constitutes a complete facial treatment"], options_es: ["Usar productos correctamente diluidos y profesionalmente apropiados, después de confirmar que el cliente no tiene alergias o sensibilidades conocidas ni condiciones que contraindiquen su uso (como el embarazo, para ciertos aceites), y discontinuar el uso si ocurre alguna irritación", "Aplicar aceites esenciales concentrados y sin diluir directamente sobre la piel del cliente para maximizar su efecto", "Usar cualquier aceite esencial en cualquier cliente, ya que los aceites esenciales no pueden causar reacciones alérgicas ni irritación de la piel", "Sustituir los aceites esenciales por todos los productos faciales estándar, ya que la aromaterapia por sí sola constituye un tratamiento facial completo"], correct: 0, explanation: "Essential oils are highly concentrated and can cause allergic reactions, sensitization, or irritation if used improperly — and certain oils may be contraindicated for specific conditions (for example, some oils are not advised during pregnancy). Appropriate use means selecting properly diluted, professional-grade products, screening for allergies and contraindications during consultation, and discontinuing use immediately if any adverse reaction occurs." },
  { id: 393, question: "What is the main reason an esthetician should perform a thorough visual and tactile assessment of the client's neck and décolleté area, not just the face, during a facial consultation?", question_es: "¿Cuál es la razón principal por la que un esteticista debe realizar una evaluación visual y táctil exhaustiva del cuello y el escote del cliente, no solo del rostro, durante una consulta facial?", options: ["These areas are often included in facial treatments and may show similar skin conditions, sun damage, or concerns as the face, so assessing them supports a complete and appropriate treatment plan", "The neck and décolleté are the only areas relevant to determining a client's overall skin type", "Assessing these areas is required so the esthetician can apply hair removal services without additional consultation", "These areas never require any product application or care during a facial treatment"], options_es: ["Estas áreas a menudo se incluyen en los tratamientos faciales y pueden mostrar condiciones de la piel, daño solar o preocupaciones similares a las del rostro, por lo que evaluarlas apoya un plan de tratamiento completo y apropiado", "El cuello y el escote son las únicas áreas relevantes para determinar el tipo de piel general de un cliente", "Evaluar estas áreas es necesario para que el esteticista pueda aplicar servicios de depilación sin consulta adicional", "Estas áreas nunca requieren aplicación de productos ni cuidado durante un tratamiento facial"], correct: 0, explanation: "The neck and décolleté are frequently included in facial treatments and are commonly exposed to the sun, so they may show similar conditions to the face — sun damage, hyperpigmentation, dryness, or breakouts. Assessing these areas as part of the overall consultation allows the esthetician to plan and provide a more complete, well-rounded treatment that addresses the client's full needs in that region." },
  { id: 394, question: "A facial treatment plan should be adjusted seasonally (for example, between summer and winter) primarily because:", question_es: "Un plan de tratamiento facial debe ajustarse estacionalmente (por ejemplo, entre el verano y el invierno) principalmente porque:", options: ["Environmental factors such as humidity, temperature, and sun exposure change with the seasons and can affect the skin's hydration, oil production, and sensitivity, calling for corresponding adjustments in products and techniques", "Skin type permanently changes from one season to another and never returns to its prior state", "Seasonal adjustment is mainly a marketing technique with no real basis in skin physiology", "Sunscreen is only necessary during summer months and should be discontinued in winter"], options_es: ["Los factores ambientales como la humedad, la temperatura y la exposición al sol cambian con las estaciones y pueden afectar la hidratación, la producción de aceite y la sensibilidad de la piel, lo que requiere ajustes correspondientes en los productos y las técnicas", "El tipo de piel cambia permanentemente de una estación a otra y nunca regresa a su estado anterior", "El ajuste estacional es principalmente una técnica de marketing sin base real en la fisiología de la piel", "El protector solar solo es necesario durante los meses de verano y debe descontinuarse en invierno"], correct: 0, explanation: "Seasonal changes in humidity, temperature, and sun exposure can influence how the skin behaves — for example, skin may become drier in low-humidity winter conditions or oilier and more sun-exposed in summer. Adjusting product recommendations (such as richer moisturizers in winter or lighter, oil-controlling formulas in summer) and treatment techniques helps address the skin's changing needs throughout the year, while daily sun protection remains important year-round." },
  { id: 395, question: "Which best describes appropriate use of LED (light-emitting diode) light therapy as part of a facial treatment, within an esthetician's scope?", question_es: "¿Cuál describe mejor el uso apropiado de la terapia de luz LED como parte de un tratamiento facial, dentro del alcance de un esteticista?", options: ["Using devices according to manufacturer guidelines and appropriate protective eyewear, selecting wavelengths suited to the client's documented concerns, and avoiding use on clients with contraindications such as certain photosensitivity conditions or medications", "Using any available wavelength at maximum intensity on every client regardless of skin type or medical history", "Allowing the client to look directly at the light source without any eye protection to enhance the treatment's effect", "Using LED therapy as a substitute for a complete consultation and skin analysis"], options_es: ["Usar los dispositivos según las pautas del fabricante y con protección ocular apropiada, seleccionando longitudes de onda adecuadas para las preocupaciones documentadas del cliente, y evitando su uso en clientes con contraindicaciones como ciertas condiciones de fotosensibilidad o medicamentos", "Usar cualquier longitud de onda disponible a máxima intensidad en todos los clientes sin importar el tipo de piel o el historial médico", "Permitir que el cliente mire directamente a la fuente de luz sin ninguna protección ocular para mejorar el efecto del tratamiento", "Usar la terapia LED como sustituto de una consulta y análisis de piel completos"], correct: 0, explanation: "LED light therapy devices should always be used according to manufacturer instructions, with appropriate protective eyewear for the client (and often the esthetician), selecting wavelengths suited to the documented concern (e.g., certain wavelengths are associated with calming or supporting the skin's appearance). Clients with photosensitivity conditions or who take photosensitizing medications may need this modality avoided or modified, and a complete consultation and analysis should always precede its use — not be replaced by it." },
  { id: 396, question: "When a client reports a stinging or burning sensation during the application of a facial product, the esthetician should:", question_es: "Cuando un cliente informa una sensación de ardor o picazón durante la aplicación de un producto facial, el esteticista debe:", options: ["Stop the application immediately, remove the product (such as by rinsing with cool water), assess the skin, and document the reaction, adjusting the treatment plan as needed", "Continue applying the product as planned, since some discomfort is always a normal and expected part of any effective treatment", "Increase the amount of product applied to overcome the sensation more quickly", "Apply a second, different active product on top to counteract the stinging sensation"], options_es: ["Detener la aplicación de inmediato, retirar el producto (por ejemplo, enjuagando con agua fría), evaluar la piel y documentar la reacción, ajustando el plan de tratamiento según sea necesario", "Continuar aplicando el producto según lo planeado, ya que cierta incomodidad siempre es una parte normal y esperada de cualquier tratamiento efectivo", "Aumentar la cantidad de producto aplicado para superar la sensación más rápidamente", "Aplicar un segundo producto activo diferente encima para contrarrestar la sensación de ardor"], correct: 0, explanation: "Stinging or burning during product application can indicate irritation, sensitivity, or an allergic-type reaction and should never be dismissed as a normal or necessary part of treatment. The appropriate response is to stop immediately, remove the product, assess the skin for redness or swelling, document what occurred, and adjust the plan — which may include discontinuing that product altogether and possibly recommending the client follow up with a healthcare provider if the reaction is significant." },
  { id: 397, question: "Which of the following best illustrates appropriate end-of-service communication during a facial treatment?", question_es: "¿Cuál de las siguientes ilustra mejor la comunicación apropiada al final del servicio durante un tratamiento facial?", options: ["Reviewing the client's skin condition, explaining recommended at-home care (including daily sun protection), suggesting an appropriate interval for follow-up visits, and answering the client's questions honestly", "Avoiding any discussion of homecare so the client must return for another appointment to learn how to care for their skin", "Pressuring the client to purchase the most expensive retail products available regardless of their needs or budget", "Ending the appointment immediately after the final product is applied with no further conversation"], options_es: ["Revisar la condición de la piel del cliente, explicar el cuidado recomendado en casa (incluida la protección solar diaria), sugerir un intervalo apropiado para las visitas de seguimiento y responder las preguntas del cliente con honestidad", "Evitar cualquier discusión sobre el cuidado en casa para que el cliente deba regresar a otra cita para aprender a cuidar su piel", "Presionar al cliente para que compre los productos de venta al por menor más caros disponibles sin importar sus necesidades o presupuesto", "Terminar la cita inmediatamente después de aplicar el último producto sin ninguna conversación adicional"], correct: 0, explanation: "Effective end-of-service communication reinforces the value of the treatment and supports good client outcomes: reviewing what was observed, explaining appropriate at-home care (always including daily sun protection), recommending a reasonable follow-up schedule based on the client's needs, and answering questions honestly — building trust rather than using pressure tactics or withholding helpful information." },
  { id: 398, question: "Why might an esthetician choose to perform a series of facial treatments over time rather than relying on a single session to address a client's skin concern (such as hyperpigmentation or texture irregularities)?", question_es: "¿Por qué podría un esteticista optar por realizar una serie de tratamientos faciales a lo largo del tiempo en lugar de depender de una sola sesión para abordar la preocupación de la piel de un cliente (como la hiperpigmentación o las irregularidades de textura)?", options: ["Many skin concerns respond gradually to consistent, appropriately spaced treatments that work with the skin's natural renewal cycle, and a series allows for monitoring progress and adjusting the approach over time", "A single session is always sufficient to permanently resolve any skin concern, making a series unnecessary in all situations", "A series of treatments is recommended purely to increase revenue and has no basis in how skin responds to treatment", "Performing treatments in a series guarantees that the client will never experience the concern again in the future"], options_es: ["Muchas preocupaciones de la piel responden gradualmente a tratamientos consistentes y adecuadamente espaciados que trabajan con el ciclo natural de renovación de la piel, y una serie permite monitorear el progreso y ajustar el enfoque con el tiempo", "Una sola sesión siempre es suficiente para resolver permanentemente cualquier preocupación de la piel, haciendo innecesaria una serie en todas las situaciones", "Una serie de tratamientos se recomienda únicamente para aumentar los ingresos y no tiene base en cómo responde la piel al tratamiento", "Realizar tratamientos en serie garantiza que el cliente nunca volverá a experimentar la preocupación en el futuro"], correct: 0, explanation: "The skin's renewal cycle and the gradual nature of many concerns (such as pigmentation, texture, or signs of aging) mean that consistent, appropriately spaced treatments often produce more meaningful and lasting improvement than a single session. A series also allows the esthetician to observe how the client's skin responds and adjust products, techniques, or frequency — an approach grounded in how skin actually changes over time, not simply a sales tactic." },
  { id: 399, question: "An esthetician notices that a client's skin appears noticeably more red and irritated than usual at the start of a scheduled follow-up facial, and the client mentions they started a new prescription medication recently. The most appropriate action is to:", question_es: "Un esteticista nota que la piel de un cliente aparece notablemente más enrojecida e irritada de lo habitual al comienzo de un facial de seguimiento programado, y el cliente menciona que comenzó recientemente un nuevo medicamento recetado. La acción más apropiada es:", options: ["Pause to reassess the treatment plan in light of the new information and current skin condition, modify or postpone more stimulating procedures as needed, and proceed only with techniques appropriate for the skin's present state", "Proceed with the treatment exactly as originally planned, since the client's appointment was already scheduled in advance", "Increase the intensity of exfoliation to address the redness more aggressively", "Tell the client that medications never affect how skin responds to treatments and continue without any changes"], options_es: ["Pausar para reevaluar el plan de tratamiento a la luz de la nueva información y la condición actual de la piel, modificar o posponer los procedimientos más estimulantes según sea necesario, y proceder solo con técnicas apropiadas para el estado actual de la piel", "Proceder con el tratamiento exactamente como se planeó originalmente, ya que la cita del cliente ya estaba programada con anticipación", "Aumentar la intensidad de la exfoliación para abordar el enrojecimiento de manera más agresiva", "Decirle al cliente que los medicamentos nunca afectan la forma en que la piel responde a los tratamientos y continuar sin ningún cambio"], correct: 0, explanation: "New medications can affect skin sensitivity, hydration, and reactivity, and observable changes in the skin's condition since the last visit are important new information. A thoughtful esthetician reassesses the plan based on what they currently observe and what the client reports, modifying or postponing procedures that could aggravate the present condition — treatment plans should be responsive to the client's current state, not rigidly fixed regardless of new findings." },
  { id: 400, question: "What is the most appropriate way for an esthetician to keep client treatment records (including products used, techniques performed, skin observations, and reactions) over time?", question_es: "¿Cuál es la forma más apropiada para que un esteticista mantenga los registros de tratamiento del cliente (incluidos los productos utilizados, las técnicas realizadas, las observaciones de la piel y las reacciones) a lo largo del tiempo?", options: ["Maintain accurate, organized, and confidential records for each visit, updating them consistently so that the esthetician (or another team member, with appropriate authorization) can reference the client's history to provide safe, informed, and consistent care going forward", "Avoid keeping any written records so that client information cannot be reviewed by anyone, including the esthetician, in the future", "Record only the client's payment information, since other details are not relevant to providing safe and effective care", "Rely solely on memory to recall details from previous visits, since written records are unnecessary for providing quality care"], options_es: ["Mantener registros precisos, organizados y confidenciales para cada visita, actualizándolos de manera constante para que el esteticista (u otro miembro del equipo, con la autorización apropiada) pueda consultar el historial del cliente para brindar una atención segura, informada y constante en el futuro", "Evitar mantener cualquier registro escrito para que la información del cliente no pueda ser revisada por nadie, incluido el esteticista, en el futuro", "Registrar solo la información de pago del cliente, ya que otros detalles no son relevantes para brindar una atención segura y eficaz", "Confiar únicamente en la memoria para recordar detalles de visitas anteriores, ya que los registros escritos son innecesarios para brindar una atención de calidad"], correct: 0, explanation: "Accurate, organized, and confidential treatment records — covering products used, techniques performed, skin observations, and any reactions — allow the esthetician (and authorized team members) to provide consistent, informed care over time, recognize patterns, avoid repeating problematic approaches, and respond appropriately to changes in the client's skin. Good recordkeeping is a hallmark of professional, client-centered practice and supports both safety and continuity of care." },
]

const ftSection = '\n  // ─── FACIAL TREATMENTS (ids 368–446) ───────────────────────────────────────\n'

let out = readFileSync(FILE, 'utf8')
out += SC.map(q => fmt(q, scT, scTes, scPt, scPtes)).join('\n') + '\n'
out += ftSection
out += FT.map(q => fmt(q, ftT, ftTes, ftPt, ftPtes)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${SC.length} Skin Care (ids ${SC[0].id}–${SC[SC.length-1].id}) + ${FT.length} Facial Treatments (ids ${FT[0].id}–${FT[FT.length-1].id})`)
